// Ad coverage per target platform: every platform the game targets that offers an ad kind the
// title commits to must have at least one placement of that kind in the integration plan.
//
// Why this exists (2026-10-21): the Y8 admin returned a game built from this template with
// "the game is missing ads". Its src/platform/integration-plan.ts - generated by the Factory's
// `sdk` step from the game-design at the time - listed its placements for the platforms of the
// ORIGINAL design (crazygames, yandex, poki). The title was then retargeted to y8; nothing
// regenerated the plan, and the y8 build shipped with game.config.yaml monetization.ad_kinds
// [interstitial, rewarded] and not one ad call: the runtime (src/platform/gameplay.ts) shows a
// placement on a target only when `platforms` is null or lists that target. Two more titles had
// the same flaw. Nothing on the game side said so; this does.
//
// The rule, for every entry of game.config.yaml platforms[] and every ad kind K:
//
//   K is in monetization.ad_kinds  AND  K is in the vendored profile's capabilities.ads
//   (config/platforms/<id>.yaml, the rules the plan was approved under)
//     => some placement of kind K in INTEGRATION_PLAN has `platforms: null` or lists <id>.
//
// The plan's own semantics are respected, exactly as gameplay.ts reads it:
//   * a placement matches by the TARGET id, never by an adapter substitute: a target built on
//     another platform's adapter (`adapterSubstitutes`) is covered only by placements listing
//     the target itself;
//   * an interstitial is also covered when the target is in `breakOnContinue`: the runtime
//     signals the portal's own ad opportunity every time play continues.
// A platform whose profile offers no ads, and an ad kind the title does not commit to, require
// nothing. A plan that does not exist yet (the Factory's `sdk` step has not integrated this
// repository) is reported as skipped, not as a pass and not as a failure: a game that has not
// been integrated fails on its own later, and the template itself ships no plan.
//
// Reads source and YAML only; builds nothing, runs nothing but the plan's own object literal
// (in an empty context, with a timeout).

import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { runInNewContext } from "node:vm";
import { parse } from "yaml";

export const PLAN_FILE = "src/platform/integration-plan.ts";
export const PROFILES_DIR = "config/platforms";

const REGENERATE =
  `Regenerate ${PLAN_FILE} with the Factory's sdk step (\`bin/wgf resume <run> --from sdk\`), ` +
  "which lists every target whose profile offers the kind; never hand-edit the generated file.";

/** Comments out, string and template contents kept: enough to find the plan's literal. */
function stripComments(text) {
  let out = "";
  let i = 0;
  while (i < text.length) {
    const char = text[i];
    const next = text[i + 1];
    if (char === '"' || char === "'" || char === "`") {
      const end = skipString(text, i);
      out += text.slice(i, end);
      i = end;
    } else if (char === "/" && next === "/") {
      while (i < text.length && text[i] !== "\n") i++;
    } else if (char === "/" && next === "*") {
      const end = text.indexOf("*/", i + 2);
      i = end === -1 ? text.length : end + 2;
    } else {
      out += char;
      i++;
    }
  }
  return out;
}

function skipString(text, start) {
  const quote = text[start];
  let i = start + 1;
  while (i < text.length && text[i] !== quote) i += text[i] === "\\" ? 2 : 1;
  return i + 1;
}

/** The text of the object literal assigned to INTEGRATION_PLAN, or null. */
export function planLiteral(source) {
  const text = stripComments(source);
  const declared = /\bINTEGRATION_PLAN\b[^=]*=/.exec(text);
  if (!declared) return null;
  const start = text.indexOf("{", declared.index + declared[0].length);
  if (start === -1) return null;
  let depth = 0;
  for (let i = start; i < text.length;) {
    const char = text[i];
    if (char === '"' || char === "'" || char === "`") {
      i = skipString(text, i);
      continue;
    }
    if (char === "{" || char === "[") depth++;
    if (char === "}" || char === "]") {
      depth--;
      if (depth === 0) return text.slice(start, i + 1);
    }
    i++;
  }
  return null;
}

/** The plan as data: { plan } or { error }. */
export function readPlan(source) {
  const literal = planLiteral(source);
  if (literal === null) return { error: `${PLAN_FILE} declares no INTEGRATION_PLAN object` };
  try {
    const plan = runInNewContext(`(${literal})`, Object.create(null), { timeout: 1000 });
    if (!plan || typeof plan !== "object" || !Array.isArray(plan.placements)) {
      return { error: `INTEGRATION_PLAN in ${PLAN_FILE} has no placements list` };
    }
    return { plan };
  } catch (error) {
    return { error: `INTEGRATION_PLAN in ${PLAN_FILE} is not a plain literal: ${error.message}` };
  }
}

/** True when a placement of `kind` in `plan` reaches `target` at runtime (gameplay.ts). */
export function covers(plan, kind, target) {
  const listed = (plan.placements ?? []).some(
    (p) =>
      p &&
      p.kind === kind &&
      (p.platforms === null || (Array.isArray(p.platforms) && p.platforms.includes(target))),
  );
  if (listed) return true;
  return kind === "interstitial" && (plan.breakOnContinue ?? []).includes(target);
}

/**
 * The ad kinds each platform must have a placement for: { required: [{platform, kind,
 * profile}], problems: [string] }. `profiles` maps platform id -> parsed profile (or null when
 * not vendored).
 */
export function requiredCoverage(gameConfig, profiles) {
  const committed = gameConfig?.monetization?.ad_kinds ?? [];
  const required = [];
  const problems = [];
  if (committed.length === 0) return { required, problems };
  for (const entry of gameConfig?.platforms ?? []) {
    const id = typeof entry === "string" ? entry : entry?.id;
    if (!id) continue;
    const profile = profiles[id];
    const path = `${PROFILES_DIR}/${id}.yaml`;
    if (!profile) {
      problems.push(
        `${id}: ${path} is not vendored, so which ad kinds ${id} offers is not established ` +
          "(the Factory vendors every pinned profile at init and on a retarget)",
      );
      continue;
    }
    const offered = profile?.capabilities?.ads ?? [];
    for (const kind of committed) {
      if (offered.includes(kind)) required.push({ platform: id, kind, profile: path });
    }
  }
  return { required, problems };
}

function readProfiles(root, gameConfig) {
  const profiles = {};
  for (const entry of gameConfig?.platforms ?? []) {
    const id = typeof entry === "string" ? entry : entry?.id;
    if (!id) continue;
    const path = resolve(root, PROFILES_DIR, `${id}.yaml`);
    profiles[id] = existsSync(path) ? parse(readFileSync(path, "utf8")) : null;
  }
  return profiles;
}

/**
 * The check. Returns { status: "pass" | "fail" | "skipped", checks: [...], problems: [...] }.
 * `gameConfig` is game.config.yaml (or the config WGF_GAME_CONFIG names) as data.
 */
export function checkAdCoverage(root, gameConfig) {
  const checks = [];
  const profiles = readProfiles(root, gameConfig);
  const { required, problems } = requiredCoverage(gameConfig, profiles);
  if (problems.length) {
    return {
      status: "fail",
      checks: problems.map((detail) => ({ id: "ads-profile", ok: false, detail })),
      problems,
    };
  }
  if (required.length === 0) {
    return {
      status: "pass",
      checks: [
        {
          id: "ads-coverage",
          ok: true,
          detail:
            "no target platform offers an ad kind game.config.yaml monetization.ad_kinds " +
            "commits to: no placement is required",
        },
      ],
      problems: [],
    };
  }
  const planPath = resolve(root, PLAN_FILE);
  if (!existsSync(planPath)) {
    return {
      status: "skipped",
      checks: [
        {
          id: "ads-coverage",
          ok: true,
          skipped: true,
          detail:
            `${PLAN_FILE} does not exist: the Factory's sdk step has not integrated this ` +
            "repository yet, so there is no plan to check. Not a pass: once it exists, every " +
            "target that offers a committed ad kind must be listed.",
        },
      ],
      problems: [],
    };
  }
  const { plan, error } = readPlan(readFileSync(planPath, "utf8"));
  if (error) {
    return {
      status: "fail",
      checks: [{ id: "ads-plan", ok: false, detail: error }],
      problems: [error],
    };
  }
  const failures = [];
  for (const { platform, kind, profile } of required) {
    const ok = covers(plan, kind, platform);
    const substitute = plan.adapterSubstitutes?.[platform];
    const listedFor = [
      ...new Set(
        (plan.placements ?? [])
          .filter((p) => p?.kind === kind)
          .flatMap((p) => (p.platforms === null ? ["every platform"] : (p.platforms ?? []))),
      ),
    ];
    const detail = ok
      ? `${platform}: a "${kind}" placement in ${PLAN_FILE} reaches ${platform}`
      : `${platform}: game.config.yaml monetization.ad_kinds commits to "${kind}" and ${profile} ` +
        `(capabilities.ads) offers it, but no "${kind}" placement in ${PLAN_FILE} lists ` +
        `${platform} (${kind} placements list: ${listedFor.join(", ") || "none"})` +
        (substitute
          ? `; ${platform} runs on the ${substitute} adapter, but placements match the target ` +
            `id, not the substitute`
          : "") +
        `. The ${platform} build would ship with no ${kind} ads. ${REGENERATE}`;
    checks.push({ id: `ads-coverage:${platform}:${kind}`, ok, detail });
    if (!ok) failures.push(detail);
  }
  return { status: failures.length ? "fail" : "pass", checks, problems: failures };
}
